<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$admin=require_admin($pdo);$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$id=(int)($_POST['user_id']??0);$tier=($_POST['plan_tier']??'free')==='pro'?'pro':'free';$expires=trim((string)($_POST['pro_expires_at']??''));try{$pdo->prepare('UPDATE users SET plan_tier=?,pro_expires_at=? WHERE id=?')->execute([$tier,$tier==='pro'&&$expires!==''?$expires:null,$id]);$success='Plan updated.';}catch(Throwable $e){$error=$e->getMessage();}}
$users=$pdo->query('SELECT id,username,display_name,email,role,plan_tier,pro_expires_at,status,created_at FROM users ORDER BY created_at DESC LIMIT 250')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Users · Annotated Admin</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/admin/">Annotated Admin</a><nav><a href="/admin/ai.php">AI</a><a href="/admin/source-monitor.php">Sources</a><a href="/admin/moderation.php">Moderation</a></nav></header><main class="panel"><h1>Users & plans</h1><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><div class="tableWrap"><table><thead><tr><th>User</th><th>Role</th><th>Plan</th><th>Joined</th><th>Change plan</th></tr></thead><tbody><?php foreach($users as $x):?><tr><td><strong><?=h($x['display_name'])?></strong><div class="meta">@<?=h($x['username'])?> · <?=h($x['email'])?></div></td><td><?=h($x['role'])?></td><td><?=h($x['plan_tier'])?><?=!empty($x['pro_expires_at'])?' until '.h($x['pro_expires_at']):''?></td><td><?=h($x['created_at'])?></td><td><form method="post" class="inlineForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="user_id" value="<?=h((string)$x['id'])?>"><select name="plan_tier"><option value="free" <?=$x['plan_tier']==='free'?'selected':''?>>Free</option><option value="pro" <?=$x['plan_tier']==='pro'?'selected':''?>>Pro</option></select><input type="datetime-local" name="pro_expires_at" value="<?=h($x['pro_expires_at']?date('Y-m-d\TH:i',strtotime($x['pro_expires_at'])):'')?>"><button>Save</button></form></td></tr><?php endforeach?></tbody></table></div></main></body></html>
